buggyCode:
List<String> cart = new ArrayList<>(List.of("milk"));
Map<List<String>, Integer> prices = new HashMap<>();
prices.put(cart, 25_000);

cart.add("bread");                 // khách thêm sản phẩm

System.out.println(prices.get(cart));
System.out.println(prices.get(List.of("milk")));
System.out.println(prices.size());
System.out.println(prices);

fix.code:
// Key phải immutable: chụp bản sao bất biến lúc put
prices.put(List.copyOf(cart), 25_000);

// Hoặc dùng record với component immutable
record CartKey(List<String> items) {
    CartKey { items = List.copyOf(items); }
}
prices.put(new CartKey(cart), 25_000);
